import logging


UNIT_OF_DT_DEFINITION_THROUGHPUT = 'k'


class IperfDataTransferConfig(object):
    def __init__(self, dt_definition, configuration):
        """
        Iperf data transfer settings from DataTransferDefinition (robot kwargs).
        :param dt_definition: DataTransferDefinition class instance
        """
        self.dt_config = {'duration': dt_definition.duration,
                          'direction': dt_definition.direction,
                          'protocol': dt_definition.protocol,
                          'bandwidth': '{}{}'.format(int(dt_definition.throughput),
                                                     UNIT_OF_DT_DEFINITION_THROUGHPUT)}
        self.dt_config.update(configuration['data_transfer'])
        self.dt_config.update({'ue_ip': configuration['ue_ip']})
        logging.debug("dt_config:{}".format(self.dt_config))
        self.iperf_interval = self.dt_config['iperf_interval']

    def get_bandwidth(self):
        """Method's name says everything."""
        if self.dt_config['protocol'] != 'udp':
            raise Exception("bandwidth is only for udp")
        if 'bandwidth' not in self.dt_config:
            raise Exception("bandwidth not defined in data transfer kwargs")
        return self.dt_config['bandwidth']

    def get_duration(self):
        """Method's name says everything."""
        return self.dt_config['duration']

    def get_direction(self):
        """Method's name says everything."""
        return self.dt_config['direction']

    def get_protocol(self):
        """Method's name says everything."""
        return self.dt_config['protocol']

    def get_app_server_config(self):
        """Method's name says everything."""
        return self.dt_config['app_server']

    def get_ue_host_config(self):
        """Method's name says everything."""
        return self.dt_config['ue_host']

    def get_iperf_options(self):
        """Method's name says everything."""
        return self.dt_config['iperf_options']

    def get_ue_ip(self):
        """Method's name says everything."""
        return self.dt_config['ue_ip']

    def get_iperf_interval(self):
        """Method's name says everything."""
        if self.iperf_interval is None or self.iperf_interval == 0:
            logging.debug('Using default iperf interval: 1')
            return 1
        logging.debug('Using iperf interval from testline config: {}'.format(self.iperf_interval))
        return int(self.iperf_interval)
